  },
  "goal": [
    {
      "id": "bump-encoding-mapping",
      "insight": "Encode each of the 8 streaming platforms as a distinct colored line across quarterly time snapshots (Q1 2019 – Q1 2025), with y-axis representing rank position (1=top), and label each line at start and end for readability"
    },
    {
      "id": "disney-rapid-ascent",
      "insight": "Visually emphasize Disney+'s dramatic rise from its launch rank (late 2019) into the top tier within just a few quarters, making the steep upward trajectory unmistakable"
    },
    {
      "id": "netflix-sustained-lead",
      "insight": "Highlight Netflix's persistent hold on the #1 rank across the entire timeline, showing its line as a stable anchor at the top of the chart"
    },
    {
      "id": "mid-tier-jostling",
      "insight": "Show the frequent rank crossovers among lower-tier platforms (Hulu, HBO Max, YouTube Premium, Apple TV+) to convey the competitive volatility in the 5th–8th rank zone"
    },
    {
      "id": "spotify-prime-contrast",
      "insight": "Contrast the relatively stable trajectories of Amazon Prime Video (consistently #2) and Spotify (alternating between #3 and #4) against the more volatile lower-tier platforms, emphasizing their consistent top-4 positioning"
    }
  ]
}

