  { name:"Amazon Prime",       key:"Amazon Prime Video", color:"#00a8e1", strokeWidth:2.5, featured:true },
  { name:"Spotify",            key:"Spotify",            color:"#1db954", strokeWidth:2.5, featured:true },
  { name:"Disney+",            key:"Disney+",            color:"#4a90d9", strokeWidth:3.0, featured:true },
  { name:"Hulu",               key:"Hulu",               color:"#3dba78", strokeWidth:1.8, featured:false },
  { name:"HBO Max",            key:"HBO Max",            color:"#9b59b6", strokeWidth:1.8, featured:false },
  { name:"YouTube Premium",    key:"YouTube Premium",    color:"#ff6b35", strokeWidth:1.8, featured:false },
  { name:"Apple TV+",          key:"Apple TV+",          color:"#b8c0cc", strokeWidth:1.8, featured:false },
];

