const DPR = window.devicePixelRatio || 1;

const PAD_LEFT   = 58;
const PAD_RIGHT  = 130;
const PAD_TOP    = 44;
const PAD_BOTTOM = 52;
const CHART_W    = Math.min(window.innerWidth - 96, 1300);
const CHART_H    = 540;

canvas.style.width  = CHART_W + 'px';
canvas.style.height = CHART_H + 'px';
canvas.width  = CHART_W * DPR;
canvas.height = CHART_H * DPR;

const ctx = canvas.getContext('2d');
ctx.scale(DPR, DPR);

// helpers
function xPos(qIdx) {
  return PAD_LEFT + (qIdx / (TOTAL_Q - 1)) * (CHART_W - PAD_LEFT - PAD_RIGHT);
}
function yPos(rank) {
  return PAD_TOP + ((rank - 1) / 7) * (CHART_H - PAD_TOP - PAD_BOTTOM);
