const yearStarts = QUARTERS.reduce((acc, q, i) => {
  if (q.startsWith('Q1')) acc.push(i);
  return acc;
}, []);

yearStarts.forEach(i => {
  const x = xPos(i);
  ctx.beginPath();
  ctx.moveTo(x, PAD_TOP - 16);
  ctx.lineTo(x, CHART_H - PAD_BOTTOM + 8);
  ctx.strokeStyle = 'rgba(255,255,255,0.07)';
  ctx.lineWidth = 1;
  ctx.setLineDash([2, 4]);
  ctx.stroke();
  ctx.setLineDash([]);

  const yr = QUARTERS[i].split(' ')[1];
  ctx.fillStyle = 'rgba(255,255,255,0.35)';
  ctx.font = `500 11px 'IBM Plex Mono', monospace`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.fillText(yr, x, CHART_H - PAD_BOTTOM + 12);
});

// ---- X-axis quarter labels (every 2nd Q, skip years already shown) ----
QUARTERS.forEach((q, i) => {
  if (q.startsWith('Q1')) return; // already shown as year
  if (i % 2 !== 0) return;
  const x = xPos(i);
  ctx.fillStyle = 'rgba(255,255,255,0.18)';
  ctx.font = `400 10px 'IBM Plex Mono', monospace`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.fillText(q.split(' ')[0], x, CHART_H - PAD_BOTTOM + 12);
});

// ---- Disney+ launch annotation ----
const disneyLaunchIdx = 3; // Q4 2019
const dxAnn = xPos(disneyLaunchIdx);
ctx.beginPath();
ctx.moveTo(dxAnn, PAD_TOP - 12);
ctx.lineTo(dxAnn, CHART_H - PAD_BOTTOM);
ctx.strokeStyle = 'rgba(74, 144, 217, 0.25)';
ctx.lineWidth = 1;
ctx.setLineDash([3, 5]);
ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = 'rgba(74, 144, 217, 0.6)';
ctx.font = `400 10px 'IBM Plex Mono', monospace`;
ctx.textAlign = 'center';
ctx.textBaseline = 'bottom';
ctx.fillText('Disney+ launch', dxAnn, PAD_TOP - 14);

// ---- Draw platform lines (back-to-front: unfeatured first) ----
const drawOrder = [...PLATFORMS].sort((a, b) => (a.featured ? 1 : 0) - (b.featured ? 1 : 0));

drawOrder.forEach(platform => {
  const points = DATA.map((d, i) => {
    const rank = d[platform.key];
    if (rank === null) return null;
    return { x: xPos(i), y: yPos(rank), rank, qi: i };
  });

  const segments = [];
  let seg = [];
  points.forEach(pt => {
    if (pt === null) {
      if (seg.length > 0) { segments.push(seg); seg = []; }
    } else {
      seg.push(pt);
    }
  });
  if (seg.length > 0) segments.push(seg);

  segments.forEach(segment => {
    if (segment.length < 2) return;

    // Draw shadow for featured lines
    if (platform.featured) {
      ctx.beginPath();
      segment.forEach((pt, i) => {
        if (i === 0) {
          ctx.moveTo(pt.x, pt.y);
        } else {
          const prev = segment[i - 1];
          const cpx = (prev.x + pt.x) / 2;
          ctx.bezierCurveTo(cpx, prev.y, cpx, pt.y, pt.x, pt.y);
        }
      });
      ctx.strokeStyle = platform.color + '33';
      ctx.lineWidth = platform.strokeWidth + 4;
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';
      ctx.stroke();
    }

    // Main line
    ctx.beginPath();
    segment.forEach((pt, i) => {
      if (i === 0) {
        ctx.moveTo(pt.x, pt.y);
      } else {
        const prev = segment[i - 1];
        const cpx = (prev.x + pt.x) / 2;
        ctx.bezierCurveTo(cpx, prev.y, cpx, pt.y, pt.x, pt.y);
      }
    });
    ctx.strokeStyle = platform.color;
    ctx.lineWidth = platform.strokeWidth;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.globalAlpha = platform.featured ? 1.0 : 0.6;
    ctx.stroke();
    ctx.globalAlpha = 1.0;
  });

  // Dots at each data point
  points.forEach(pt => {
    if (!pt) return;
    const r = platform.featured ? 4 : 2.5;
    ctx.beginPath();
    ctx.arc(pt.x, pt.y, r, 0, Math.PI * 2);
    ctx.fillStyle = platform.featured ? platform.color : platform.color + '99';
    ctx.fill();
    if (platform.featured) {
      ctx.strokeStyle = '#0d1117';
      ctx.lineWidth = 1.5;
      ctx.stroke();
    }
  });
});

// ---- End labels (right side) ----
const lastQ = DATA[DATA.length - 1];

// Collect final ranks to sort labels by position
const finalLabels = PLATFORMS.map(p => {
  const rank = lastQ[p.key];
  if (rank === null) return null;
  return { name: p.name, color: p.color, rank, featured: p.featured };
}).filter(Boolean).sort((a, b) => a.rank - b.rank);

const LBL_X = CHART_W - PAD_RIGHT + 14;

finalLabels.forEach(lbl => {
  const y = yPos(lbl.rank);
  ctx.fillStyle = lbl.featured ? lbl.color : lbl.color + 'aa';
  ctx.font = lbl.featured
    ? `600 12.5px 'IBM Plex Sans', sans-serif`
    : `400 11px 'IBM Plex Sans', sans-serif`;
  ctx.textAlign = 'left';
  ctx.textBaseline = 'middle';
  ctx.fillText(lbl.name, LBL_X, y);
});

// ---- Start labels (left side, only first 3 or 4 stable ones) ----
const firstQ = DATA[0];
const startLabels = PLATFORMS.map(p => {
  const rank = firstQ[p.key];
  if (rank === null) return null;
  return { name: p.name, color: p.color, rank, featured: p.featured };
}).filter(Boolean);

startLabels.forEach(lbl => {
  const y = yPos(lbl.rank);
  ctx.fillStyle = lbl.featured ? lbl.color + 'cc' : 'rgba(255,255,255,0.15)';
  ctx.font = `400 10.5px 'IBM Plex Sans', sans-serif`;
  ctx.textAlign = 'right';
  ctx.textBaseline = 'middle';
  ctx.fillText(lbl.name, PAD_LEFT - 30, y);
});

// ---- Y-axis label ----
ctx.save();
ctx.translate(13, (PAD_TOP + CHART_H - PAD_BOTTOM) / 2);
ctx.rotate(-Math.PI / 2);
ctx.fillStyle = 'rgba(255,255,255,0.25)';
ctx.font = `400 11px 'IBM Plex Mono', monospace`;
ctx.textAlign = 'center';
ctx.textBaseline = 'middle';
ctx.fillText('RANK POSITION', 0, 0);
ctx.restore();

// ---- Title band ----
ctx.fillStyle = 'rgba(255,255,255,0.06)';
ctx.fillRect(PAD_LEFT - 6, PAD_TOP - 32, CHART_W - PAD_LEFT - PAD_RIGHT + 6, 22);

// ---- Build legend ----
const legend = document.getElementById('legend');
PLATFORMS.forEach(p => {
  const item = document.createElement('div');
  item.className = 'legend-item' + (p.featured ? ' featured' : '');
  item.innerHTML = `
    <div class="legend-swatch" style="background:${p.color}; opacity:${p.featured ? '1' : '0.55'}"></div>
    <span class="legend-label">${p.name}</span>
  `;
  legend.appendChild(item);
});
</script>
</body>
