const puppeteer = require('puppeteer');
const path = require('path');

(async () => {
  const browser = await puppeteer.launch({
    args: ['--no-sandbox', '--disable-setuid-sandbox', '--disable-dev-shm-usage']
  });
  const page = await browser.newPage();

  await page.setViewport({ width: 1440, height: 780, deviceScaleFactor: 2 });

  const filePath = path.resolve('/app/output/bump_chart.html');
  await page.goto('file://' + filePath, { waitUntil: 'networkidle0', timeout: 30000 });

  // Wait for fonts + canvas render
  await new Promise(r => setTimeout(r, 1200));

  await page.screenshot({
    path: '/app/output/result.png',
    fullPage: false,
    clip: { x: 0, y: 0, width: 1440, height: 780 }
  });

  await browser.close();
  console.log('Done: /app/output/result.png');
})();
